autoPtr<volScalarField> rAUOwner
(
    new volScalarField(1.0/UEqn.A())
);
volScalarField& rAU=rAUOwner();
C29::managedGeometricField(rAU,"rAU");

autoPtr<volVectorField> HbyAOwner
(
    new volVectorField(constrainHbyA(rAU*UEqn.H(),U,p))
);
volVectorField& HbyA=HbyAOwner();
C29::managedGeometricField(HbyA,"HbyA");

autoPtr<surfaceScalarField> phiHbyAOwner
(
    new surfaceScalarField(
    "phiHbyA",fvc::flux(HbyA)
    +fvc::interpolate(rAU)*C29::eulerPhiCorrection(U,phi)
)
);
surfaceScalarField& phiHbyA=phiHbyAOwner();
C29::managedGeometricField(phiHbyA,"phiHbyA");

autoPtr<fvScalarMatrix> pEqnOwner
(
    new fvScalarMatrix(
    fvm::laplacian(rAU,p)==fvc::div(phiHbyA)
)
);
fvScalarMatrix& pEqn=pEqnOwner();
C29::managedMatrix(pEqn,"pEqn");

autoPtr<volScalarField> pOwner
(
    new volScalarField(
    IOobject
    (
        "p",
        runTime.timeName(),
        mesh,
        IOobject::MUST_READ,
        IOobject::AUTO_WRITE
    ),
    mesh
)
);
volScalarField& p=pOwner();
C29::managedGeometricField(p,"p");

autoPtr<volVectorField> UOwner
(
    new volVectorField(
    IOobject
    (
        "U",
        runTime.timeName(),
        mesh,
        IOobject::MUST_READ,
        IOobject::AUTO_WRITE
    ),
    mesh
)
);
volVectorField& U=UOwner();
C29::managedGeometricField(U,"U");

autoPtr<volScalarField> nuEffOwner
(
    new volScalarField(
    IOobject("nuEff",runTime.constant(),mesh,IOobject::NO_READ,IOobject::NO_WRITE,false),
    mesh,nu
)
);
volScalarField& nuEff=nuEffOwner();
C29::managedGeometricField(nuEff,"nuEff");

autoPtr<surfaceScalarField> phiOwner
(
    new surfaceScalarField(
    IOobject
    (
        "phi",
        runTime.timeName(),
        mesh,
        IOobject::READ_IF_PRESENT,
        IOobject::AUTO_WRITE
    ),
    fvc::flux(U)
)
);
surfaceScalarField& phi=phiOwner();
C29::managedGeometricField(phi,"phi");

autoPtr<surfaceVectorField> devTauCorrFluxOwner
(
    new surfaceVectorField(
    "devTauCorrFlux",
    -nuFace*fvc::dotInterpolate(mesh.Sf(),dev2(T(fvc::grad(U))))
)
);
surfaceVectorField& devTauCorrFlux=devTauCorrFluxOwner();
C29::managedGeometricField(devTauCorrFlux,"devTauCorrFlux");

autoPtr<surfaceScalarField> dPhiOwner
(
    new surfaceScalarField(
    "c29EulerDeltaPhi",
    phi.oldTime()-fvc::dotInterpolate(mesh.Sf(),U.oldTime())
)
);
surfaceScalarField& dPhi=dPhiOwner();
C29::managedGeometricField(dPhi,"dPhi");

autoPtr<surfaceScalarField> couplingOwner
(
    new surfaceScalarField(
    "c29EulerCoupling",
    scalar(1)-min
    (
        mag(dPhi)/(mag(phi.oldTime())+dimensionedScalar
        (
            "small",phi.dimensions(),std::numeric_limits<scalar>::epsilon()
        )),
        scalar(1)
    )
)
);
surfaceScalarField& coupling=couplingOwner();
C29::managedGeometricField(coupling,"coupling");

autoPtr<fvVectorMatrix> sourceOwner
(
    new fvVectorMatrix(U,UEqn.dimensions())
);
fvVectorMatrix& source=sourceOwner();
C29::managedMatrix(source,"source");
